assignments.value:
={{ (() => {
  const text = $json.output;
  const anfrage = $('Anfrage (Chat)').item.json.chatInput || '';
  const en = (anfrage.match(/\b(the|and|we|our|would|could|please|offer|hello|you|for)\b/gi) || []).length;
  const de = (anfrage.match(/\b(und|wir|unsere|unser|bitte|fuer|der|die|das|ein|eine|ist)\b/gi) || []).length;
  const englisch = en > de;
  if (/Aussortiert|Discarded/i.test(text)) return text;
  const hinweis = englisch && /Gesamtpreis/.test(text) ? '\n\nNote: The price breakdown above is provided in German.' : '';
  const ki = englisch ? 'This draft was created with AI assistance.' : 'Dieser Entwurf wurde mit KI-Unterstützung erstellt.';
  return text + hinweis + '\n\n' + ki;
})() }}
